/** One of a person's holds: from its from-date to its to-date (null: open-ended), both inclusive. */
interface DatedHold {
  from: string;
  to: string | null;
}

/** Whether a day lies within one of the person's holds. */
function heldOn(p: Person, date: string): boolean {
  return p.holds.some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/**
 * Whether a claim of the person counts toward the totals: an OPEN or PENDING claim dated within one
 * of their holds does not, unless a statement binds it.
 */
function countsFor(p: Person | undefined, c: Claim): boolean {
  return counts(c) && (c.stated || !(p !== undefined && isOpen(c) && heldOn(p, c.date)));
}

/** One of a person's patrons. */
interface PatronLink {
 * charge is never bound by a statement; a settled claim's due already holds the charge it was
 * settled with. Null when it has no figure.
 */
export function chargedDueCents(
  c: Claim,
  rates: readonly Rate[],
  grade: string,
  floors: readonly DatedValue[],
  late: Lateness,
  roundOn: string,
): number | null {
  const halfUp = roundsHalfUp(roundOn, late.policyDate, late.today);
  const figure = claimDueCents(c, rates, grade, cents(valueOn(floors, c.date, START_FLOOR)), halfUp);
  if (figure === null || !isOpen(c) || isCorrection(c)) return figure;
  const periods = Math.floor(daysOverdue(c, late.today) / 30);
  if (periods <= 0) return figure;
  return figure + (dueCents(figure * periods, valueOn(late.latePcts, c.date, START_LATE_PCT), halfUp) ?? 0);
}

/** A due in whole cents with two decimals, or n/a when there is no rate. */
export function dueText(c: number | null): string {
  return c === null ? 'n/a' : money(c);
}

